mapper.select:
SELECT 1 AS report_type, DATE_FORMAT(r.create_time, '%Y-%m') AS statistic_period, -- CONCAT('REPORT', DATE_FORMAT(now(), '%Y-%m'), r.ent_id) AS report_no, CONCAT('REPORT', DATE_FORMAT(ANY_VALUE(r.create_time), '%Y-%m'), r.ent_id) AS report_no, r.ent_id, e.ent_name, '低风险' AS risk_level, e.area_name AS area, e.ent_type_name AS ent_type, MIN(r.create_time) AS begin_time, MAX(r.create_time) AS end_time, COUNT(r.id) AS violation_count, ROUND( (COUNT(DISTINCT CASE WHEN r.review_status = '已完成' THEN r.id END) / COUNT(DISTINCT r.id)) * 100, 2 ) AS rectify_finish_rate FROM rectify_review r LEFT JOIN enterprise_info e ON r.ent_id = e.id WHERE r.deleted = 0 AND e.deleted = 0
AND DATE_FORMAT(r.create_time, '%Y-%m') = #{statisticPeriod}
AND e.area_name = #{area}
AND e.ent_type_name = #{entType}
AND r.create_time >= #{beginTime}
AND r.create_time <= #{endTime}
AND e.ent_name LIKE CONCAT('%', #{entName}, '%')
AND CONCAT('REPORT', DATE_FORMAT(r.create_time, '%Y-%m'), r.ent_id) LIKE CONCAT('%', #{reportNo}, '%')
AND CONCAT('REPORT', DATE_FORMAT(r.create_time, '%Y-%m'), r.ent_id) IN
#{reportNo}
GROUP BY r.ent_id, DATE_FORMAT(r.create_time, '%Y-%m')
ORDER BY DATE_FORMAT(r.create_time, '%Y-%m') desc,r.ent_id DESC
LIMIT #{pageSize} OFFSET ${(pageNo - 1) * pageSize}

SELECT
    e.ent_name AS entName,
    COUNT(r.id) AS violationCount
FROM rectify_review r
LEFT JOIN enterprise_info e ON r.ent_id = e.id
WHERE r.deleted = 0
  AND e.deleted = 0

    AND DATE_FORMAT(r.create_time, '%Y-%m') = #{statisticPeriod}


    AND e.area_name = #{area}


    AND e.ent_type_name = #{entType}


    AND r.create_time >= #{beginTime}


    AND r.create_time <= #{endTime}


    AND e.ent_name LIKE CONCAT('%', #{entName}, '%')


    AND CONCAT('REPORT', DATE_FORMAT(r.create_time, '%Y-%m'), r.ent_id) LIKE CONCAT('%', #{reportNo}, '%')


    AND CONCAT('REPORT', DATE_FORMAT(r.create_time, '%Y-%m'), r.ent_id) IN

        #{reportNo}


GROUP BY r.ent_id
ORDER BY violationCount DESC

SELECT COUNT(*) FROM (
                         SELECT 1
                         FROM rectify_review r
                                  LEFT JOIN enterprise_info e ON r.ent_id = e.id
                         WHERE r.deleted = 0
                           AND e.deleted = 0


                            AND DATE_FORMAT(r.create_time, '%Y-%m') = #{statisticPeriod}


                            AND e.area_name = #{area}


                            AND e.ent_type_name = #{entType}


                            AND r.create_time >= #{beginTime}


                            AND r.create_time <= #{endTime}


                            AND e.ent_name LIKE CONCAT('%', #{entName}, '%')



                            AND CONCAT('REPORT', DATE_FORMAT(r.create_time, '%Y-%m'), r.ent_id) LIKE CONCAT('%', #{reportNo}, '%')



                            AND CONCAT('REPORT', DATE_FORMAT(r.create_time, '%Y-%m'), r.ent_id) IN

                                #{reportNo}


                         GROUP BY r.ent_id, DATE_FORMAT(r.create_time, '%Y-%m')
                     ) AS temp
